import random

def reservoir(stream, k):
    """蓄水池抽样 k 个:前 k 个直接装满池;第 i 个(i>k,1-based)以 k/i
    概率入选,入选则随机替换池中某一格。一遍流、O(k) 空间,每元素入选概率 k/n。
    流长不足 k 时返回整条流。"""
    pool = []
    for i, x in enumerate(stream, start=1):
        if i <= k:
            pool.append(x)
        else:
            j = random.randint(1, i)        # 1..i;命中 [1,k] 的概率为 k/i
            if j <= k:
                pool[j - 1] = x
    return pool
